-- https://lua.expert/
local StatModifierManager = require(game.ReplicatedStorage.Modules.Data.StatModifierManager)
local t = {}
local t2 = {
	Name = "Ribbon Spool",
	Icon = "rbxassetid://17653810096",
	Rarity = "Common",
	Description = "Gain 10% more Walk and Run Speed on even numbered floors.",
	TrinketType = "Toggle",
	MonsterTrinket = true,
	Cost = 350
}

t2.Requirement1 = { "Coin", t2.Cost }
function t2.ApplyTrinket(p1, p2) --[[ ApplyTrinket | Line: 20 | Upvalues: t (copy), StatModifierManager (copy) ]]
	local Active = p2:WaitForChild("Active")

	Active.Value = false

	local function togglestats() --[[ togglestats | Line: 26 | Upvalues: t (ref), p1 (copy), StatModifierManager (ref), Active (copy) ]]
		if workspace.Info.Floor.Value == 0 or workspace.Info.Floor.Value == 1 then
			return
		end

		if workspace.Info.Floor.Value % 2 == 0 then
			if not t[p1] then
				t[p1] = StatModifierManager.ApplySpeedModifiers(p1, 1.1, "RibbonSpool", {
					category = "trinket"
				})
			end

			Active.Value = true
		else
			if t[p1] then
				StatModifierManager.RemoveSpeedModifiers(p1, t[p1])
				t[p1] = nil
			end

			Active.Value = false
		end
	end

	togglestats()
	workspace.Info.Floor.Changed:Connect(togglestats)
end
function t2.RemoveTrinket(p1) --[[ RemoveTrinket | Line: 49 | Upvalues: t (copy), StatModifierManager (copy) ]]
	local Trinkets = p1:WaitForChild("Trinkets")
	local Trinket1 = Trinkets:FindFirstChild("Trinket1")
	local Trinket2 = Trinkets:FindFirstChild("Trinket2")

	if not (Trinket1 and Trinket2) then
		return "CantRemove"
	end

	if Trinket1.Value == script.Name then
		local Active = Trinket1:FindFirstChild("Active")

		Trinket1.Value = "None"

		if not Active or (Active.Value ~= true or not t[p1]) then
			return "Slot1"
		end

		StatModifierManager.RemoveSpeedModifiers(p1, t[p1])
		t[p1] = nil

		return "Slot1"
	end

	if Trinket2.Value ~= script.Name then
		return "CantRemove"
	end

	local Active = Trinket2:FindFirstChild("Active")

	Trinket2.Value = "None"

	if not Active or (Active.Value ~= true or not t[p1]) then
		return "Slot2"
	end

	StatModifierManager.RemoveSpeedModifiers(p1, t[p1])
	t[p1] = nil

	return "Slot2"
end

return t2